import * as React from "react";

export type JoystickIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function JoystickIcon({ size = 20, ...props }: JoystickIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="16.5" r="4.5" /><circle cx="12" cy="7" r="2.5" /><path d="M12 9.5v7" />
    </svg>
  );
}
